import React from 'react';
import {
    Card,
    CardContent,
    Typography,
    Box,
    Skeleton,
    alpha,
} from '@mui/material';
import TrendingUpIcon from '@mui/icons-material/TrendingUp';
import TrendingDownIcon from '@mui/icons-material/TrendingDown';
import TrendingFlatIcon from '@mui/icons-material/TrendingFlat';

interface MetricCardProps {
    title: string;
    value: string | number;
    unit?: string;
    trend?: 'up' | 'down' | 'stable';
    change?: string;
    icon?: React.ReactNode;
    color?: 'primary' | 'success' | 'warning' | 'error' | 'info';
    loading?: boolean;
}

const colorMap = {
    primary: '#0D63F4',
    success: '#16A34A',
    warning: '#F59E0B',
    error: '#DC2626',
    info: '#2563EB',
};

const MetricCard: React.FC<MetricCardProps> = ({
    title,
    value,
    unit = '',
    trend,
    change,
    icon,
    color = 'primary',
    loading = false,
}) => {
    const mainColor = colorMap[color];

    const getTrendIcon = () => {
        if (!trend) return null;

        const iconProps = { fontSize: 'small' as const, sx: { ml: 0.5 } };

        switch (trend) {
            case 'up':
                return <TrendingUpIcon {...iconProps} sx={{ ...iconProps.sx, color: '#16A34A' }} />;
            case 'down':
                return <TrendingDownIcon {...iconProps} sx={{ ...iconProps.sx, color: '#DC2626' }} />;
            case 'stable':
                return <TrendingFlatIcon {...iconProps} sx={{ ...iconProps.sx, color: '#6B7280' }} />;
            default:
                return null;
        }
    };

    if (loading) {
        return (
            <Card sx={{ height: '100%' }}>
                <CardContent>
                    <Skeleton variant="text" width="60%" height={24} />
                    <Skeleton variant="text" width="80%" height={48} sx={{ mt: 2 }} />
                    <Skeleton variant="text" width="40%" height={20} sx={{ mt: 1 }} />
                </CardContent>
            </Card>
        );
    }

    return (
        <Card
            sx={{
                height: '100%',
                position: 'relative',
                overflow: 'visible',
                transition: 'all 0.3s ease',
                '&:hover': {
                    transform: 'translateY(-4px)',
                    boxShadow: '0 12px 24px rgba(0, 0, 0, 0.1)',
                },
            }}
        >
            <CardContent sx={{ p: 3 }}>
                <Box display="flex" justifyContent="space-between" alignItems="flex-start">
                    <Box flex={1}>
                        <Typography
                            variant="body2"
                            color="text.secondary"
                            fontWeight={600}
                            gutterBottom
                            sx={{ textTransform: 'uppercase', letterSpacing: '0.5px', fontSize: '0.75rem' }}
                        >
                            {title}
                        </Typography>

                        <Box display="flex" alignItems="baseline" mt={1.5}>
                            <Typography
                                variant="h3"
                                fontWeight={800}
                                sx={{
                                    color: mainColor,
                                    lineHeight: 1,
                                }}
                            >
                                {value}
                            </Typography>
                            {unit && (
                                <Typography
                                    variant="h6"
                                    color="text.secondary"
                                    fontWeight={600}
                                    sx={{ ml: 1 }}
                                >
                                    {unit}
                                </Typography>
                            )}
                        </Box>

                        {(trend || change) && (
                            <Box display="flex" alignItems="center" mt={1.5}>
                                {getTrendIcon()}
                                {change && (
                                    <Typography
                                        variant="body2"
                                        fontWeight={600}
                                        sx={{
                                            ml: 0.5,
                                            color: trend === 'up' ? '#16A34A' : trend === 'down' ? '#DC2626' : '#6B7280',
                                        }}
                                    >
                                        {change}
                                    </Typography>
                                )}
                            </Box>
                        )}
                    </Box>

                    {icon && (
                        <Box
                            sx={{
                                width: 56,
                                height: 56,
                                borderRadius: 3,
                                display: 'flex',
                                alignItems: 'center',
                                justifyContent: 'center',
                                backgroundColor: alpha(mainColor, 0.1),
                                color: mainColor,
                                flexShrink: 0,
                                ml: 2,
                            }}
                        >
                            {icon}
                        </Box>
                    )}
                </Box>
            </CardContent>
        </Card>
    );
};

export default MetricCard;
